create extension if not exists pgcrypto;
create or replace function public.get_event_access_status(p_event uuid) returns table(role_name text, enabled boolean) language sql stable security definer set search_path=public as $$ select wanted.role_name,coalesce(bool_or(c.enabled),false) from (values ('admin'),('ref'),('judge'),('inspection'),('emcee')) wanted(role_name) left join public.event_access_credentials c on c.event_id=p_event and c.role=wanted.role_name where exists(select 1 from public.event_members m where m.event_id=p_event and m.user_id=auth.uid() and m.role='admin') group by wanted.role_name order by wanted.role_name; $$;
create or replace function public.set_event_role_code(p_event uuid,p_role text,p_credential text,p_enabled boolean default true) returns void language plpgsql security definer set search_path=public as $$ declare v_code text:=upper(trim(coalesce(p_credential,''))); v_name text; begin if not exists(select 1 from public.event_members m where m.event_id=p_event and m.user_id=auth.uid() and m.role='admin') then raise exception 'Admin access required'; end if; if p_role not in ('admin','ref','judge','inspection','emcee') then raise exception 'Unsupported event role'; end if; v_name:=case p_role when 'admin' then 'admin_keypad' else p_role||'_code' end; if not p_enabled then if p_role='admin' then raise exception 'Admin access cannot be disabled'; end if; update public.event_access_credentials set enabled=false,updated_at=now() where event_id=p_event and role=p_role; return; end if; if v_code !~ '^[0-9][A-Z][0-9][0-9]$' then raise exception 'Code must be number, letter A-Z, number, number'; end if; insert into public.event_access_credentials(event_id,credential_name,role,credential_hash,enabled) values(p_event,v_name,p_role,encode(extensions.digest(v_code,'sha256'::text),'hex'),true) on conflict(event_id,credential_name) do update set role=excluded.role,credential_hash=excluded.credential_hash,enabled=true,updated_at=now(); end; $$;
revoke all on function public.get_event_access_status(uuid) from public,anon; grant execute on function public.get_event_access_status(uuid) to authenticated;
revoke all on function public.set_event_role_code(uuid,text,text,boolean) from public,anon; grant execute on function public.set_event_role_code(uuid,text,text,boolean) to authenticated;
